package main

/*
#cgo CFLAGS: -I.
#cgo LDFLAGS: -L. -ltick
#include "tick.h"

//export goTickCallback
static void goTickCallback(void* goFunc, const TickResult* r, void* ctx) {
    // This is a placeholder - actual implementation uses go runtime cgo callbacks
}
*/
import "C"
import (
    "runtime"
    "sync"
    "unsafe"
)

type Tick struct {
    Timestamp int64
    Price     float64
}

type TickResult struct {
    Timestamp int64
    Price     float64
    Status    int
}

type resultCollector struct {
    results []TickResult
    mu      sync.Mutex
    done    chan struct{}
    err     error
}

func ProcessTicks(ticks []Tick) ([]TickResult, error) {
    if len(ticks) == 0 {
        return nil, nil
    }

    collector := &resultCollector{
        results: make([]TickResult, 0, len(ticks)),
        done:    make(chan struct{}),
    }

    // Convert Go slice to C array
    cTicks := (*C.tick)(unsafe.Pointer(&ticks[0]))
    cLen := C.size_t(len(ticks))

    // Use runtime.SetCgoWolfmark for callback registration
    runtime.LockOSThread()

    ret := C.process_ticks_async(
        cTicks,
        cLen,
        C.TickResultCallback(C.tick_result_callback_trampoline),
        unsafe.Pointer(collector),
    )

    if ret != 0 {
        return nil, C.GoString(C.ticker_error())
    }

    <-collector.done
    return collector.results, collector.err
}

//export tick_result_callback_trampoline
func tick_result_callback_trampoline(r *C.tick_result, ctx unsafe.Pointer) {
    collector := (*resultCollector)(ctx)

    // CRITICAL: Copy data into Go-owned memory before any C cleanup
    result := TickResult{
        Timestamp: int64(r.ts),
        Price:     float64(r.price),
        Status:    int(r.status),
    }

    collector.mu.Lock()
    collector.results = append(collector.results, result)
    collector.mu.Unlock()
}
```

```go
// worker_pool.go - Worker pool with batch processing
package main

import (
    "context"
    "errors"
    "fmt"
    "sync"
    "sync/atomic"
)

type BatchResult struct {
    BatchID int
    Results []TickResult
    Err     error
}

type WorkerPool struct {
    workers    int
    resultCh   chan BatchResult
    wg         sync.WaitGroup
    ctx        context.Context
    cancel     context.CancelFunc
}

func NewWorkerPool(workers int, bufferSize int) *WorkerPool {
    ctx, cancel := context.WithCancel(context.Background())
    return &WorkerPool{
        workers:  workers,
        resultCh: make(chan BatchResult, bufferSize),
        ctx:      ctx,
        cancel:   cancel,
    }
}

func (wp *WorkerPool) ProcessBatches(batches [][]Tick) ([]TickResult, error) {
    var totalResults []TickResult
    var wg sync.WaitGroup
    var errCount int32

    for i, batch := range batches {
        select {
        case <-wp.ctx.Done():
            return totalResults, wp.ctx.Err()
        default:
        }

        wg.Add(1)
        go func(batchID int, ticks []Tick) {
            defer wg.Done()

            results, err := ProcessTicks(ticks)
            if err != nil {
                atomic.AddInt32(&errCount, 1)
                wp.resultCh <- BatchResult{
                    BatchID: batchID,
                    Err:     err,
                }
                return
            }

            wp.resultCh <- BatchResult{
                BatchID: batchID,
                Results: results,
            }
        }(i, batch)
    }

    go func() {
        wg.Wait()
        close(wp.resultCh)
    }()

    for result := range wp.resultCh {
        if result.Err != nil {
            return totalResults, fmt.Errorf("batch %d failed: %w", result.BatchID, result.Err)
        }
        totalResults = append(totalResults, result.Results...)
    }

    if errCount > 0 {
        return totalResults, fmt.Errorf("%d batches failed", errCount)
    }

    return totalResults, nil
}

func (wp *WorkerPool) Shutdown() {
    wp.cancel()
    wp.wg.Wait()
}

// Example usage
func main() {
    // Create sample batches
    batches := [][]Tick{
        {{Timestamp: 1000, Price: 100.0}, {Timestamp: 1001, Price: 101.0}},
        {{Timestamp: 1002, Price: 102.0}, {Timestamp: 1003, Price: 103.0}},
    }

    pool := NewWorkerPool(4, len(batches))
    results, err := pool.ProcessBatches(batches)
    if err != nil {
        fmt.Printf("Error: %v\n", err)
        return
    }

    fmt.Printf("Processed %d results\n", len(results))
    pool.Shutdown()
}
```

## Common Pitfalls
1. **Passing Go pointers to C**: Always allocate C memory or copy to Go slices first
2. **Callback thread safety**: Use `runtime.LockOSThread()` for cgo callbacks
3. **Memory lifetime**: Ensure Go slice outlives the C call that references it
4. **Error handling across FFI**: Return error strings from C, convert to Go errors

## Why This Is Asked
This question tests CGO cross-language callback design, memory ownership semantics, and thread-safety under streaming workloads.

## Key Concepts
- **CGO callbacks and pointer safety**: Go pointers cannot be passed directly to C; doing so violates CGO safety rules and causes undefined behavior.
- **Registry pattern**: Use a map keyed by uintptr to manage context across the language boundary, avoiding direct Go pointer exposure to C.
- **Memory ownership**: Each JSON chunk must be copied by Go and freed by C—clearly define who owns what to prevent leaks or use-after-free bugs.
- **Concurrency safety**: Employ locking mechanisms and per-call context isolation to safely handle concurrent streaming operations.
- **Error propagation**: Route errors from C back to Go through the context object, ensuring failures are communicated reliably.

## Code Example
```c
// C header
typedef struct {
    void (*cb)(const char* json, size_t len, void* ctx);
    void* ctx;
} StreamContext;

void register_stream(int n, const char** items, void (*cb)(const char* json, size_t len, void* ctx), void* ctx);
```

```go
// Go implementation
package main

/*
#include <stdlib.h>
typedef struct {
    void (*cb)(const char*, size_t, void*);
    void* ctx;
} StreamContext;

extern void register_stream(int n, char** items, void (*cb)(const char*, size_t, void*), void* ctx);
*/
import "C"

import (
    "fmt"
    "sync"
    "unsafe"
)

var (
    contextRegistry = make(map[uintptr]*CallContext)
    registryMu      sync.RWMutex
)

type CallContext struct {
    ResultChan chan string
    ErrorChan  chan error
    Once       sync.Once
}

export func streamCallback(json *C.char, length C.size_t, ctx unsafe.Pointer) {
    registryMu.RLock()
    callCtx, ok := contextRegistry[uintptr(ctx)]
    registryMu.RUnlock()

    if !ok {
        return
    }

    goBytes := C.GoBytes(unsafe.Pointer(json), C.int(length))
    jsonStr := string(goBytes)

    callCtx.Once.Do(func() {
        close(callCtx.ResultChan)
        close(callCtx.ErrorChan)
    })

    select {
    case callCtx.ResultChan <- jsonStr:
    default:
    }

    C.free(unsafe.Pointer(json))
}

func StartStream(items []string, batchSize int) (<-chan string, <-chan error) {
    resultChan := make(chan string, batchSize)
    errorChan := make(chan error, 1)

    callCtx := &CallContext{
        ResultChan: resultChan,
        ErrorChan:  errorChan,
    }

    ctxKey := uintptr(unsafe.Pointer(&callCtx))

    registryMu.Lock()
    contextRegistry[ctxKey] = callCtx
    registryMu.Unlock()

    cItems := make([]*C.char, len(items))
    for i, item := range items {
        cItems[i] = C.CString(item)
    }
    defer func() {
        for _, cItem := range cItems {
            C.free(unsafe.Pointer(cItem))
        }
    }()

    C.register_stream(
        C.int(len(cItems)),
        (**C.char)(unsafe.Pointer(&cItems[0])),
        (unsafe.Pointer)(C.streamCallback),
        unsafe.Pointer(ctxKey),
    )

    return resultChan, errorChan
}
```

